window.NPC_CHUNK_19 = [{"name":"Ilora Nuski","cr":12,"xp":19200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":13}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":25,"ac_touch":15,"ac_flat_footed":22,"ac_mods":"+5 armor, +2 deflection, +2 Dex, +1 dodge, +4 natural, +1 shield","hp":123,"hd":"13d10+52","hd_value":13,"fort":10,"ref":10,"will":6,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":30}],"melee":"+1 short sword +16 (1d6+4/17-20), +1 short sword +16 (1d6+4/17-20)","ranged":"dagger +15 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"Human +6, giant +4, fey +2"},{"type":"quarry"}],"spellsprepared_caster_level":10,"spellsprepared_concentration":12,"spellsprepared":[{"spell_level":3,"spell_slots":1,"spells":[{"spell":"summon nature's ally III"}]},{"spell_level":2,"spell_slots":3,"spells":[{"spell":"barkskin"},{"spell":"cure light wounds"},{"spell":"summon nature's ally II"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"alarm"},{"spell":"endure elements"},{"spell":"entangle"},{"spell":"summon nature's ally I"}]}],"strength":16,"dexterity":14,"constitution":15,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":13,"cmb":16,"cmd":31,"feats":[{"feat":"Dodge"},{"feat":"Double Slice"},{"feat":"Endurance"},{"feat":"Greater Two- Weapon Fighting"},{"feat":"Improved Critical (short sword)"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Toughness"},{"feat":"Two- Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Two-Weapon Rend"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Climb","value":19},{"skill":"Handle Animal","value":15},{"skill":"Intimidate","value":15},{"skill":"Perception","value":18},{"skill":"Stealth","value":18},{"skill":"Survival","value":18},{"skill":"Swim","value":19}],"languages":["Common"],"sq":["camouflage","favored terrain (urban +6, mountains +4, forest +2)","hunter's bond (companions)","swift tracker","track +13","wild empathy +12","woodland stride"],"gear":"+2 studded leather, 2 +1 short swords (2), amulet of natural armor +1, boots of striding and springing, ring of protection +2, 5 gp, wand of cure moderate wounds (30 charges)","before_combat":"Ilora casts alarm every evening to protect her campsite and endure elements every morning to make her life more bearable. She casts barkskin as soon as she fears combat is imminent.","during_combat":"Ilora takes advantage of woodland stride and uses the thorns to her advantage, gaining soft cover against foes farther than 5 ft. away from her. She fights with both swords, using Vital Strike when she has to move up to attack a foe. She relies on her spells to protect her from foes who use ranged attacks against her.","morale":"If faced with a foe she's obviously outnumbered or outmatched by, Ilora flees; throwing her life away on a pointless battle won't get Pitax out from under Irovetti's rule, after all.","source":"AP 35"},{"name":"Tree That Weeps","cr":14,"xp":38400,"race":"quickwood","age_category":"Adult","alignment":"N","size":"Huge","type":"plant","templates_applied":"advanced","init":3,"senses":["darkvision 120 ft.","oaksight","tremorsense 60 ft."],"ac":29,"ac_touch":7,"ac_flat_footed":29,"ac_mods":"-1 Dex, +22 natural, -2 size","hp":210,"hd":"20d8+120","hd_value":20,"fort":18,"ref":5,"will":8,"defensive_abilities":["spell absorption"],"immunities":["electricity","fire","plant traits"],"sr":25,"speed":[{"type":"land","speed":10}],"melee":"bite +23 (2d6+10/19-20), 6 roots +21 (1d6+5/19-20 plus pull)","space":"5 ft.","reach":"15 ft. (60 ft. with root)","special_attacks":[{"type":"pull","details":"30 feet"}],"strength":31,"dexterity":8,"constitution":23,"intelligence":12,"wisdom":15,"charisma":18,"baseatk":15,"cmb":27,"cmd":36,"feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Knowledge (nature)","value":21},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":14,"special":"+2 in forests"}],"languages":["Common","Sylvan"],"special_abilities":[{"type":"Fear Aura","kind":"Su","details":"As long as the quickwood retains energy it has absorbed from a spell, it can release that energy as a swift action to create a fear aura with a radius of 10 ft. per level of the spell it absorbed and released. All creatures in this aura must make a DC 24 Will save or become panicked. The fear aura lasts until the end of the quickwood's next turn. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Oaksight","kind":"Su","details":"A quickwood may observe the area surrounding any oak tree within 360 ft. as if using clairaudience/ clairvoyance. It can use this ability on any number of oak trees in the area. Although the quickwood doesn't need line of sight to establish this link, if it does have line of sight to even a single oak tree, it cannot be flanked."},{"type":"Roots","kind":"Ex","details":"A quickwood has dozens of long roots, but can only attack with up to six of them in any given round. If the quickwood uses its pull ability to pull a target within reach of its bite attack, it can immediately make a free bite attack with a +4 bonus on its attack roll against that target."},{"type":"Spell Absorption","kind":"Su","details":"If a quickwood's spell resistance protects it from being affected by a spell, the quickwood absorbs that spell's energy into its body. It can then release this energy to create a fear aura. The quickwood cannot absorb another spell's energy while it contains a previously absorbed spell's energy. As long as a quickwood is storing spell energy, attempts to overcome its spell resistance receive a +5 bonus on the roll."}],"during_combat":"The Tree That Weeps already has a 5th-level spell stored in its body from a previous fight, and unleashes its energy on the first round of combat to create a fear aura once foes come within 40 ft. of it. It then uses its roots to attack foes and pull them close so it can bite them.","morale":"The Tree That Weeps fights to the death.","source":"AP 35, Tome of Horrors Revised 302"},{"name":"Gaetane","cr":12,"xp":19200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":12}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human","shapechanger"],"templates_applied":"wererat","init":5,"senses":["low-light vision","scent"],"ac":28,"ac_touch":15,"ac_flat_footed":23,"ac_mods":"+5 armor, +5 Dex, +6 natural, +2 shield","hp":150,"hd":"12d10+84","hd_value":12,"fort":16,"ref":15,"will":10,"defensive_abilities":["evasion"],"dr":"10/silver","speed":[{"type":"land","speed":40}],"melee":"bite +16 (1d6+5 plus curse of lycanthropy and disease)","ranged":"+1 humanbane composite longbow +19 (1d8+1/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"Human +6, dwarf +4, animal +2"},{"type":"quarry"}],"spellsprepared_caster_level":9,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":3,"spell_slots":1,"spells":[{"spell":"greater magic fang"}]},{"spell_level":2,"spell_slots":3,"spells":[{"spell":"barkskin"},{"spell":"bear's endurance"},{"spell":"hold animal"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"jump"},{"spell":"longstrider"},{"spell":"resist energy"}]}],"strength":15,"dexterity":20,"constitution":22,"intelligence":8,"wisdom":14,"charisma":8,"baseatk":12,"cmb":14,"cmd":29,"feats":[{"feat":"Deadly Aim"},{"feat":"Endurance"},{"feat":"Improved Critical (composite longbow)"},{"feat":"Improved Precise Shot"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Pinpoint Targeting"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":16,"special":"+34 jumping"},{"skill":"Climb","value":16},{"skill":"Handle Animal","value":8},{"skill":"Knowledge (geography)","value":8},{"skill":"Perception","value":17},{"skill":"Stealth","value":19},{"skill":"Survival","value":17}],"languages":["Common"],"sq":["camouflage","favored terrain (urban +4, mountain +2)","hunter's bond (companions)","swift tracker","track +6","wild empathy +11","woodland stride"],"gear":"+1 chain shirt, +1 buckler, +1 humanbane composite longbow, bracers of archery, cloak of resistance +2, potion of cure serious wounds","before_combat":"Gaetane casts greater magic fang every day, and casts barkskin, bear's endurance, jump, and longstrider before entering combat.","during_combat":"Gaetane remains in the rafters, where he grants favored enemy bonuses to his soldiers and fires arrows at the PCs, preferably at Human targets. If confronted in melee, he uses Vital Strike and bites foes, using Acrobatics to jump from one end of the chamber to the other to prevent foes from making full attacks on him.","morale":"Gaetane fights until reduced to 20 hit points or less, at which point he cowardly surrenders and attempts to bargain with the PCs, offering to exchange information for his life. If any other soldiers remain alive at this time, they drop their weapons and surrender as well. You can use Gaetane to fill the PCs in on the truth about the \"poison plot\" and even to give them additional information they can use against Irovetti when they attack his palace.","source":"AP 35, Pathfinder RPG Bestiary 197"},{"name":"The Gardener","cr":13,"xp":25600,"race":"halfling","gender":"Male","age_category":"Adult","classes":[{"class":"monk","level":4},{"class":"sorcerer","level":8}],"alignment":"LE","size":"Small","type":"undead","sub_types":["augmented","halfling","incorporeal"],"templates_applied":"ghost","init":5,"senses":["darkvision 60 ft."],"ac":32,"ac_touch":28,"ac_flat_footed":26,"ac_mods":"+4 armor, +6 deflection, +5 Dex, +1 dodge, +4 monk Wisdom, +1 size","hp":138,"hd":"4d8+8d6+92","hd_value":12,"fort":13,"ref":12,"will":15,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation evasion"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +8 (13d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acidic ray","details":"1d6+4 acid, 9/day"},{"type":"corrupting gaze","details":"DC 22"},{"type":"horrific appearance","details":"DC 22"},{"type":"telekinesis"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":8,"spellsknown_concentration":14,"spellsknown":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"black tentacles"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"haste"},{"spell":"tongues"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"cat's grace"},{"spell":"owl's wisdom"},{"spell":"see invisibility"},{"spell":"touch of idiocy"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"chill touch"},{"spell":"enlarge person"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"silent image"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"arcane mark"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"}]}],"bloodline":"aberrant","dexterity":21,"intelligence":12,"wisdom":18,"charisma":22,"baseatk":7,"cmb":7,"cmd":33,"feats":[{"feat":"Ability Focus (corrupting gaze)"},{"feat":"Arcane Strike"},{"feat":"Combat Reflexes"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Improved Unarmed Strike"},{"feat":"Lunge"},{"feat":"Mobility"},{"feat":"Silent Spell"},{"feat":"Stunning Fist"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":7,"special":"-2 jump"},{"skill":"Bluff","value":21},{"skill":"Climb","value":2},{"skill":"Fly","value":24},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":11},{"skill":"Stealth","value":24}],"languages":["Common","Gnome","Halfling"],"sq":["bloodline arcana","fast movement","ki pool (6 points, magic)","long limbs (+5 ft.)","maneuver training","slow fall 20 ft.","still mind"],"special_abilities":[{"type":"Horrific Appearance","kind":"Su","details":"As a standard action at will, the gardener can cause his appearance to burst into a riot of mold and decay, turning his ghostly body into a hideous garden of fungus and ruin. All living creatures within a 30- foot radius that view this shift must make a DC 22 Will save or be panicked for 1d4 rounds. This is a mind-affecting fear effect. A creature that saves against this ability is immune to its effects for 24 hours."}],"gear":"rod of lesser quicken metamagic","before_combat":"In the rounds before it appears, the gardener casts cat's grace, owl's wisdom, and mage armor on himself.","during_combat":"The gardener uses his corrupting gaze throughout any combat. On the first round, he attacks with his horrific appearance and a quickened haste spell. On the second round, he casts black tentacles and a quickened magic missile. On the third round, he uses telekinesis to attempt to bull rush a heavily armored foe into the surrounding pool, then moves to the most wounded target and casts a quickened vampiric touch. Once he's used all three charges of his rod of lesser quicken metamagic, he begins attacking with his corrupting touch, using telekinesis and his spells against foes who maintain ranged superiority.","morale":"The gardener fights to the death; once he appears, he pursues his victims anywhere they flee on Whiterose Hill, but not beyond the stone wall that surrounds the place.","source":"AP 35, Pathfinder RPG Bestiary 144"},{"name":"Evindra","cr":10,"xp":9600,"race":"nereid","gender":"Female","age_category":"Adult","alignment":"CN","size":"Medium","type":"fey","sub_types":["aquatic","water"],"init":9,"senses":["low-light vision"],"auras":["beguiling aura"],"ac":25,"ac_touch":25,"ac_flat_footed":15,"ac_mods":"+5 deflection, +9 Dex, +1 dodge","hp":126,"hd":"12d6+84","hd_value":12,"fort":11,"ref":17,"will":14,"defensive_abilities":["transparency"],"dr":"10/cold iron","immunities":["cold","poison"],"sr":21,"weaknesses":["shawl"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"poison touch +10 (poison)","ranged":"poison spray +15 (poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drowning kiss"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"suggestion","details":"only against creatures fascinated by her beguiling aura"}]},{"frequency":"1/day","spells":[{"spell":"summon monster VI","details":"water elemental only"}]}],"strength":11,"dexterity":29,"constitution":24,"intelligence":14,"wisdom":22,"charisma":21,"baseatk":6,"cmb":15,"cmd":31,"feats":[{"feat":"Ability Focus (poison)"},{"feat":"Agile Maneuvers"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Escape Artist","value":24},{"skill":"Knowledge (nature)","value":17},{"skill":"Perception","value":21},{"skill":"Perform (sing)","value":20},{"skill":"Sense Motive","value":21},{"skill":"Stealth","value":24},{"skill":"Swim","value":23}],"languages":["Common","Aquan","Sylvan"],"sq":["amphibious","change shape (medium water elemental, elemental body II)","unearthly grace"],"special_abilities":[{"type":"Beguiling Aura","kind":"Su","details":"Any creature who is sexually attracted to women runs the risk of being beguiled by a nereid if he or she looks upon her beauty from a distance of 30 ft. or less. Creatures who fail a DC 21 Will save are immediately fascinated. The nereid may use her suggestion spell-like ability at will against creatures that are fascinated by her beguiling aura. This is a mind-affecting compulsion effect. The save DC is Charisma-based."},{"type":"Drowning Kiss","kind":"Su","details":"A nereid can flood the lungs of a willing, helpless, or fascinated creature by touching him (traditionally by kissing him on the lips). The target immediately begins to drown if he cannot breathe water. On his turn, the kissed creature can attempt to cough up this supernatural water by succeeding on a DC 23 Fortitude save; otherwise he begins to drown (Pathfinder RPG Core Rulebook 445). Each round the drowning continues, the victim may attempt a new DC 23 Fortitude save to cough up the water. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Touch or spray (range 30 ft.)-contact; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d2 Con plus blindness; cure 2 consecutive saves."},{"type":"Shawl","kind":"Ex","details":"A nereid's shawl (hardness 2, hp 6), contains a portion of her life force. If the shawl is ever destroyed, the nereid takes 1d6 points of Constitution drain per hour until she dies. The nereid can craft a new shawl from water by making a DC 25 Will save, but each attempt takes 1d4 hours to complete. Attempts to destroy or steal the shawl should be treated as sunder or disarm attempts."},{"type":"Transparency","kind":"Su","details":"When underwater, a nereid's body becomes transparent, effectively rendering her invisible. She can become visible or transparent at will as a free action."},{"type":"Unearthly Grace","kind":"Su","details":"A nereid adds her Charisma modifier as a racial bonus on all her saving throws, and as a deflection bonus to her Armor Class as long as she wears no armor."}],"during_combat":"Evindra casts summon monster VI to conjure a water elemental on the first round of combat, then retreats into the water and uses poison against the PCs. If this tactic proves unworkable, she assumes the form of a water elemental to attack physically.","morale":"If reduced to 30 hit points or fewer, Evindra attempts to flee into the nearby pool to hide.","source":"AP 35, Tome of Horrors Revised 276-278"},{"name":"Troll Guard","cr":10,"xp":9600,"race":"troll","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":5}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["giant"],"init":4,"senses":["darkvision 60 ft.","low-light vision"],"ac":27,"ac_touch":13,"ac_flat_footed":23,"ac_mods":"+9 armor, +4 Dex, +5 natural, -1 size","hp":146,"hd":"6d8+5d10+92","hd_value":11,"hp_mods":"regeneration 5 (acid or fire)","fort":16,"ref":7,"will":3,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":20}],"melee":"mwk battleaxe +15 (2d6+11/19-20/x3), mwk battleaxe +15 (2d6+11/19-20/x3), bite +11 (1d8+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d6+7"}],"strength":26,"dexterity":18,"constitution":25,"intelligence":6,"wisdom":11,"charisma":4,"baseatk":9,"cmb":18,"cmd":32,"feats":[{"feat":"Combat Reflexes"},{"feat":"Double Slice"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Quick Draw"},{"feat":"Toughness"},{"feat":"Two-Weapon Fighting"},{"feat":"Unseat"},{"feat":"Weapon Focus (battleaxe)"},{"feat":"Weapon Specialization (battleaxe)"}],"skills":[{"skill":"Perception","value":11}],"languages":["Giant"],"sq":["armor training 1"],"gear":"full plate, masterwork battleaxes (2), 200 gp","during_combat":"In battle, the guards focus attacks on foes who use fire or acid, working together to destroy these threats first, and then turn their attacks on the most heavily armored foes.","morale":"The troll guards fight to the death.","source":"AP 35, Pathfinder RPG Bestiary 268"},{"name":"King Castruccio Irovetti","cr":16,"xp":76800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":11},{"class":"fighter","level":5}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"senses":["darkvision 60 ft.","see invisibility"],"ac":32,"ac_touch":19,"ac_flat_footed":27,"ac_mods":"+11 armor, +3 deflection, +4 Dex, +2 dodge, +2 natural","hp":188,"hd":"11d8+5d10+107","hd_value":16,"fort":16,"ref":17,"will":13,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic, +1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":60}],"melee":"rod of razors +25 (1d10+17/19-20/x3)","ranged":"flechettes +24 (1d8+13/19-20/x3)","space":"5 ft.","reach":"5 ft. (10 ft. with rod of razors)","special_attacks":[{"type":"bardic performance 36 rounds/day","details":"move action; countersong, dirge of doom, distraction, fascinate, inspire competence +4, inspire courage +3, inspire greatness, suggestion"}],"spellsknown_caster_level":11,"spellsknown_concentration":17,"spellsknown":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"dimension door"},{"spell":"dominate person"},{"spell":"greater invisibility"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"charm monster"},{"spell":"displacement"},{"spell":"phantom steed"},{"spell":"scrying"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"cat's grace"},{"spell":"cure moderate wounds"},{"spell":"detect thoughts"},{"spell":"glitterdust"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"cure light wounds"},{"spell":"expeditious retreat"},{"spell":"undetectable alignment"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":18,"dexterity":18,"constitution":20,"intelligence":12,"wisdom":8,"charisma":22,"baseatk":13,"cmb":17,"cmd":35,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Extend Spell"},{"feat":"Extra Performance"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perform sing)"},{"feat":"Spell Focus (enchantment)"},{"feat":"Toughness"},{"feat":"Weapon Focus (rod of razors)"},{"feat":"Weapon Specialization (rod of razors)"}],"skills":[{"skill":"Intimidate","value":20},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (local)","value":14},{"skill":"Knowledge (nobility)","value":14},{"skill":"Linguistics","value":5},{"skill":"Perception","value":18},{"skill":"Perform (dance)","value":20},{"skill":"Perform (oratory)","value":25},{"skill":"Perform (sing)","value":31},{"skill":"Ride","value":13},{"skill":"Use Magic Device","value":25}],"languages":["Common","Hallit","Skald; tongues"],"sq":["armor training 1","bardic knowledge +5","contingency","improved resources","jack-of-all-trades (use any skill)","lore master 2/day","permanent spells","versatile performance (oratory, sing, dance)"],"special_abilities":[{"type":"Contingency","details":"King Irovetti used a scroll to cast contingency: if he ever takes more than 10 points of damage from a single attack, a dimension door whisks him away (in this case, to his den in area T1). Improved Resources Not only does King Irovetti have the resources of a PC as regards his gear, but his ability scores use a 20-point build. Permanent Spells King Irovetti has used scrolls of permanency to gain the following permanent spell effects: darkvision, see invisibility, and tongues."}],"gear":"+5 mithral breastplate, rod of razors, amulet of natural armor +2, boots of speed, cloak of resistance +4, ring of protection +3, master key (unlocks all locks in the palace), mindrender baton, potions of lesser restoration (4), scroll of heal, scroll of restoration, scroll of teleport, wand of hold monster (CL 10th, 13 charges)","before_combat":"King Irovetti casts three alarm spells every morning (one at area Q1, one at Q10, and one at T3), along with undetectable alignment and unseen servant so he never has to take time to open doors on his own. If an alarm is raised, he also casts cat's grace on himself.","during_combat":"King Irovetti activates his boots of speed at the start of combat, along with his inspire courage ability-both of these effects are calculated in the stat block above. For the first few rounds of combat, he lets his guards enter melee while he hangs back and casts displacement and various ranged attack spells. If he's still around after 3 rounds, his increased courage leads him to enter melee wielding his rod of razors. He always uses Arcane Strike when he attacks (this damage bonus is included in his stats above).","morale":"King Irovetti flees via his dimension door contingency if he ever takes more than 10 points of damage from a single attack. He also flees via dimension door to area T1 if he's reduced to 100 hit points or fewer or is otherwise hurt badly by a magical effect that doesn't do hit point damage. He resorts to greater invisibility and physical retreat if he can't teleport.","source":"AP 35"},{"name":"General Avinash Jurrg","cr":14,"xp":38400,"race":"ogre mage","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":10}],"alignment":"LE","size":"Large","type":"outsider","sub_types":["giant","native","oni","shapechanger"],"init":8,"senses":["darkvision 60 ft.","low-light vision"],"ac":26,"ac_touch":13,"ac_flat_footed":22,"ac_mods":"+8 armor, +4 Dex, +5 natural, -1 size","hp":243,"hd":"8d10+10d8+154","hd_value":18,"hp_mods":"regeneration 5 (acid or fire)","fort":19,"ref":15,"will":16,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","sr":19,"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"+2 keen greatsword +25 (3d6+15/17-20)","ranged":"+1 composite longbow +19 (2d6+1/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bardic performance 28 rounds/day","details":"move action; countersong, dirge of doom, distraction, fascinate, inspire competence +3, inspire courage +2, inspire greatness, suggestion"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"}]},{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"invisibility"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"cone of cold"},{"spell":"deep slumber"},{"spell":"gaseous form"}]}],"spellsknown_caster_level":10,"spellsknown_concentration":16,"spellsknown":[{"spell_level":4,"spell_slots":2,"spells":[{"spell":"dimension door"},{"spell":"hold monster"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"confusion"},{"spell":"dispel magic"},{"spell":"good hope"},{"spell":"haste"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blur"},{"spell":"cure moderate wounds"},{"spell":"mirror image"},{"spell":"rage"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"charm person"},{"spell":"cure light wounds"},{"spell":"expeditious retreat"},{"spell":"grease"},{"spell":"remove fear"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"know direction"},{"spell":"mage hand"},{"spell":"message"},{"spell":"summon instrument"}]}],"strength":28,"dexterity":19,"constitution":26,"intelligence":14,"wisdom":12,"charisma":22,"baseatk":15,"cmb":25,"cmd":39,"feats":[{"feat":"Arcane Armor Mastery"},{"feat":"Arcane Armor Training"},{"feat":"Arcane Strike"},{"feat":"Armor Proficiency (Medium)"},{"feat":"Combat Expertise"},{"feat":"Greater Disarm"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":22},{"skill":"Fly","value":17},{"skill":"Knowledge (arcana)","value":19},{"skill":"Knowledge (engineering)","value":19},{"skill":"Knowledge (nobility)","value":19},{"skill":"Perception","value":22},{"skill":"Perform (oratory)","value":27},{"skill":"Perform (percussion)","value":27},{"skill":"Perform (wind)","value":27},{"skill":"Spellcraft","value":14}],"languages":["Common","Giant"],"sq":["bardic knowledge +5","change shape (Small, Medium, or Large humanoid, alter self or giant form 1)","jack-of-all-trades (use any skill)","lore master 1/day","versatile performance (oratory, percussion, wind)"],"gear":"+2 mithral breastplate, +2 keen greatsword, +1 composite longbow with 20 arrows, cloak of resistance +2","during_combat":"Jurrg lets his minions engage foes in melee so he can take the time to bolster their powers, first by casting good hope and activating inspire courage, followed by casting haste, rage, and mirror image before he enters melee.","morale":"As long as any of Jurrg's minions still stand, he fights to the death. If he's alone and Irovetti still lives, he fights until reduced to 100 hit points or fewer, at which point he casts dimension door to go wherever he believes Irovetti is located to report to his king. When fighting at Irovetti's side or defending the throne room itself, he fights to the death.","source":"AP 35, Pathfinder RPG Bestiary 221"},{"name":"Alasen","cr":13,"xp":25600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":14}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human","shapechanger"],"templates_applied":"afflicted weretiger","init":7,"senses":["low-light vision","scent"],"ac":27,"ac_touch":17,"ac_flat_footed":23,"ac_mods":"+5 armor, +3 deflection, +3 Dex, +1 dodge, +5 natural","hp":161,"hd":"14d8+98","hd_value":14,"fort":9,"ref":14,"will":6,"defensive_abilities":["improved evasion","improved uncanny dodge","trap sense +4"],"dr":"5/silver","speed":[{"type":"land","speed":35}],"melee":"2 claws +16 (1d8+6 plus grab), bite +16 (2d6+6 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +16, 1d8+6"},{"type":"sneak attack","details":"+7d6"}],"strength":23,"dexterity":17,"constitution":20,"intelligence":8,"wisdom":14,"charisma":12,"baseatk":10,"cmb":16,"cmd":33,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Fleet"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Wind Stance"}],"skills":[{"skill":"Acrobatics","value":20},{"skill":"Climb","value":23},{"skill":"Escape Artist","value":20},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19},{"skill":"Sleight of Hand","value":20},{"skill":"Stealth","value":20},{"skill":"Survival","value":16}],"languages":["Common"],"sq":["change shape (Human, hybrid, and tiger; polymorph)","improved uncanny dodge","rogue talents (bleeding attack +6, combat trick, crippling strike, fast stealth, improved evasion, slippery mind, surprise attack)","trapfinding +7"],"gear":"+3 leather armor, ring of invisibility, ring of protection +3","during_combat":"Alasen prefers to wait for the PCs to be engaged in a battle with other defenders of the palace, so that she can skulk into place and attack from invisibility with pounce. She retreats to invisibility after attacking, then repositions for another attack; she does her best to avoid ever being caught in melee for more than a few rounds at a time.","morale":"Alasen's loyalty to Irovetti collapses if she's reduced to fewer than 40 hit points, at which point she attempts to flee the palace and Pitax altogether.","source":"AP 35"},{"name":"Gedovius","cr":12,"xp":19200,"race":"gargoyle","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":10}],"alignment":"NE","size":"Medium","type":"monstrous humanoid","sub_types":["earth"],"init":8,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":16,"ac_flat_footed":22,"ac_mods":"+7 armor, +1 deflection, +4 Dex, +1 dodge, +4 natural","hp":162,"hd":"5d10+10d8+90","hd_value":15,"fort":9,"ref":15,"will":7,"defensive_abilities":["improved evasion","improved uncanny dodge","trap sense +3"],"dr":"10/magic","speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"2 claws +17 (1d6+4/19-20), bite +16 (1d6+4), gore +16 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack +5d6 plus 5 bleed"}],"strength":19,"dexterity":18,"constitution":20,"intelligence":8,"wisdom":11,"charisma":5,"baseatk":12,"cmb":16,"cmd":32,"feats":[{"feat":"Dazzling Display"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Shatter Defenses"},{"feat":"Toughness"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":22},{"skill":"Escape Artist","value":17},{"skill":"Fly","value":17},{"skill":"Intimidate","value":15},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":22}],"languages":["Common","Terran"],"sq":["freeze","rogue talents (bleeding attack, combat trick, fast stealth, improved evasion, surprise attack)","trapfinding +5"],"gear":"+4 studded leather, amulet of natural armor +1, ring of protection +1","during_combat":"When fighting with his hounds, Gedovius moves to flank foes. On his own, he uses Dazzling Display to intimidate foes, then uses Shatter Defenses against shaken enemies so that his latter attacks in the same round become sneak attacks.","morale":"Gedovius fights to the death.","source":"AP 35, Pathfinder RPG Bestiary 137"},{"name":"Rezatha","cr":15,"xp":51200,"race":"remorhaz","age_category":"Adult","alignment":"N","size":"Huge","type":"magical beast","templates_applied":"advanced","init":8,"senses":["darkvision 60 ft.","low-light vision","tremorsense 60 ft."],"ac":26,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+4 Dex, +1 dodge, +13 natural, -2 size","hp":270,"hd":"20d10+160","hd_value":20,"fort":19,"ref":16,"will":9,"immunities":["cold","fire"],"speed":[{"type":"burrow","speed":20},{"type":"land","speed":30}],"melee":"bite +21 (8d6+31 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"heat"},{"type":"swallow whole","details":"4d6+9 plus 8d6 fire, AC 16, hp 27"}],"strength":28,"dexterity":18,"constitution":25,"intelligence":9,"wisdom":16,"charisma":14,"baseatk":20,"cmb":31,"cmd":46,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (Bite)"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Perception","value":26}],"languages":["Common","Giant (cannot speak)"],"during_combat":"Rezatha always attacks using Power Attack and Vital Strike-a particularly devastating combination, given the size and strength of its jaws.","morale":"Rezatha fights to the death.","source":"AP 35, Pathfinder RPG Bestiary 233, 294"},{"name":"Engelidis","cr":14,"xp":38400,"race":"spirit naga","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":5}],"alignment":"CE","size":"Large","type":"aberration","init":4,"senses":["darkvision 60 ft."],"ac":34,"ac_touch":17,"ac_flat_footed":30,"ac_mods":"+4 armor, +4 deflection, +4 Dex, +9 natural, +4 shield, -1 size","hp":157,"hd":"10d8+5d6+95","hd_value":15,"fort":10,"ref":8,"will":17,"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":40},{"type":"swim","speed":20}],"melee":"+1 bite +15 (3d6+10/19-20 plus poison [DC 21])","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"charming gaze","details":"DC 21"},{"type":"laughing touch","details":"9/day"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":12,"spellsknown_concentration":18,"spellsknown":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"chain lightning"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"breath of life"},{"spell":"telekinesis"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"death ward"},{"spell":"dimension door"},{"spell":"ice storm"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"clairaudience/ clairvoyance"},{"spell":"dispel magic"},{"spell":"fly"},{"spell":"lightning bolt"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"alter self"},{"spell":"cure moderate wounds"},{"spell":"hideous laughter"},{"spell":"invisibility"},{"spell":"misdirection"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"entangle"},{"spell":"mage armor"},{"spell":"ray of enfeeblement"},{"spell":"shield"},{"spell":"shield of faith"},{"spell":"shocking grasp"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"create water"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/ close"},{"spell":"stabilize"}]}],"bloodline":"fey","strength":22,"dexterity":18,"constitution":23,"intelligence":12,"wisdom":19,"charisma":22,"baseatk":9,"cmb":16,"cmd":34,"feats":[{"feat":"Ability Focus (charming gaze)"},{"feat":"Arcane Strike"},{"feat":"Eschew Materials"},{"feat":"Extend Spell"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell"}],"skills":[{"skill":"Fly","value":15},{"skill":"Knowledge (arcana)","value":9},{"skill":"Knowledge (dungeoneering)","value":9},{"skill":"Perception","value":22},{"skill":"Spellcraft","value":19},{"skill":"Stealth","value":18},{"skill":"Swim","value":14}],"languages":["Common","Abyssal"],"sq":["bloodline arcana","woodland stride"],"gear":"spell storing amulet of mighty fists +1 (contains hideous laughter)","before_combat":"Engelidis casts mage armor, death ward, fly, shield, and shield of faith before entering combat.","during_combat":"On her own, Engelidis uses her area-affecting spells to damage as many foes as possible as quickly as possible. When fighting alongside King Irovetti, she takes a more supportive role, targeting those foes who seem to be specifically causing her lover the most harm and trouble.","morale":"As long as she's charmed by Irovetti, Engelidis fights to the death. If the charm monster spell on the spirit naga is removed or dispelled, Engelidis won't see things Irovetti's way. In fact, her rage and hatred in such a situation compels her to do everything in her power to murder Irovetti-as in the case with the remorhaz Rezatha, this gives the PCs a chance to swiftly recruit the king's allies against him in a battle. Of course, in her rage, Engelidis is unwilling to retain her loyalty to the PCs after Irovetti is dead; she tries to escape at once, and if the PCs oppose her flight, she attacks them as well. Engelidis knows about the sword Irovetti keeps hidden in area T3. She offers up its location as a bargaining chip to the PCs if she thinks that could help to buy her freedom and she's too wounded to carry on a fight against them.","source":"AP 35, Pathfinder RPG Bestiary 213"},{"name":"Mandragora Swarm","cr":13,"xp":25600,"race":"mandragora","age_category":"Adult","alignment":"CE","size":"Fine","type":"plant","sub_types":["swarm"],"templates_applied":"swarm","init":13,"senses":["low-light vision"],"ac":28,"ac_touch":28,"ac_flat_footed":18,"ac_mods":"+9 Dex, +1 dodge, +8 size","hp":220,"hd":"21d8+126","hd_value":21,"hp_mods":"fast healing 10","fort":19,"ref":18,"will":8,"defensive_abilities":["swarm traits"],"immunities":["plant traits","weapon damage"],"resists":["acid 5","cold 5","electricity 10"],"weaknesses":["vulnerable to darkness"],"speed":[{"type":"land","speed":30}],"melee":"swarm +23 (5d6 plus blood drain, distraction, and poison)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 25"},{"type":"shriek"}],"strength":11,"dexterity":29,"constitution":20,"intelligence":8,"wisdom":13,"charisma":10,"baseatk":15,"cmb":16,"cmd":27,"feats":[{"feat":"Ability Focus (poison)"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":14},{"skill":"Stealth","value":45,"special":"+8 in heavy plant growth"}],"languages":["Common","Abyssal"],"sq":["hive mind","vines"],"special_abilities":[{"type":"Blood Drain","kind":"Ex","details":"Whenever a mandragora swarm damages a foe with its swarm damage, it also drains blood, dealing 1d6 points of Strength damage. A mandragora that drains blood from a target with 0 Strength instead deals 2d4 points of Constitution damage."},{"type":"Hive Mind","kind":"Ex","details":"The mandragora swarm has one central mind, but retains its immunity to mind-affecting effects due to its plant traits."},{"type":"Poison","kind":"Ex","details":"Swarm-injury; save Fort DC 27; frequency 1/round for 6 rounds; effect confused for 1 round; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Shriek","kind":"Su","details":"Once per day as a standard action, a mandragora swarm can give voice to an unsettling shriek that sounds not unlike the cry of a thousand tiny babies. Any creature within 30 ft. of a shrieking mandragora swarm must make a DC 25 Will save or become nauseated for 1d4 rounds. This is a sonic, mind-affecting effect. The save DC is Constitution-based."},{"type":"Vulnerable to Darkness","kind":"Ex","details":"A mandragora swarm in an area of darkness loses its fast healing and becomes slowed, as per the spell."}],"during_combat":"A mandragora swarm begins battle by shrieking. It then swarms over as many foes as it can, chewing and draining blood and leaving confused victims in its wake.","morale":"A mandragora swarm fights to the death.","source":"AP 36, Pathfinder Adventure Path #17 84, Advanced Bestiary 45"},{"name":"The Horned Hunter","cr":16,"xp":76800,"race":"satyr","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":12}],"alignment":"CN","size":"Medium","type":"fey","init":10,"senses":["low-light vision"],"ac":31,"ac_touch":17,"ac_flat_footed":24,"ac_mods":"+5 armor, +6 Dex, +1 dodge, +9 natural","hp":206,"hd":"8d6+12d10+112","hd_value":20,"fort":14,"ref":20,"will":15,"defensive_abilities":["evasion"],"dr":"5/cold iron","speed":[{"type":"land","speed":40}],"melee":"+2 horns +23 (1d6+9)","ranged":"+3 seeking composite longbow +23 (1d8+19/19-20/x3) or Rapid Shot +21 (1d8+19/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"Human +6, elf +4, gnome +2"},{"type":"pipes"},{"type":"quarry"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm person"},{"spell":"dancing lights"},{"spell":"ghost sound"},{"spell":"sleep"},{"spell":"suggestion"}]},{"frequency":"1/day","spells":[{"spell":"fear"},{"spell":"summon nature's ally III"}]}],"spellsknown_caster_level":9,"spellsknown_concentration":13,"spellsknown":[{"spell_level":3,"spell_slots":2,"spells":[{"spell":"cure moderate wounds"},{"spell":"greater magic fang"}]},{"spell_level":2,"spell_slots":3,"spells":[{"spell":"barkskin"},{"spell":"cat's grace"},{"spell":"protection from energy"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"charm animal"},{"spell":"entangle"},{"spell":"pass without trace"}]}],"strength":20,"dexterity":23,"constitution":18,"intelligence":10,"wisdom":16,"charisma":19,"baseatk":16,"cmb":21,"cmd":38,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Improved Critical (composite longbow)"},{"feat":"Improved Initiative"},{"feat":"Improved Precise Shot"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Shot on the Run"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Acrobatics","value":29,"special":"+4 jump"},{"skill":"Escape Artist","value":29},{"skill":"Knowledge (nature)","value":23},{"skill":"Perception","value":26},{"skill":"Stealth","value":29},{"skill":"Survival","value":26}],"languages":["Common","Sylvan"],"sq":["camouflage","favored terrain (forest +4, plains +2)","hunter's bond (companions)","swift tracker","track +6","wild empathy +16","woodland stride"],"gear":"+3 leather armor, +3 seeking composite longbow with 20 arrows, greater bracers of archery, helm of teleportation","before_combat":"The Horned Hunter casts greater magic fang on his horns every day. Before entering battle, he casts barkskin and cat's grace on himself.","during_combat":"The Horned Hunter always uses Deadly Aim in battle, and prefers to use Rapid Shot as often as he can. On the first round of combat, he grants his favored enemy bonus to his ettins via his hunter's bond. Although his natural inclination is to fire upon humans before any other target, if it's obvious who's carrying Briar, he and his ettins focus their attacks on that target. The Horned Hunter's not really interested in slaying the entire party as much as he is in capturing Briar. If the person carrying Briar is defeated, the Horned Hunter claims the sword as soon as he can, teleporting to the Castle of Knives after claiming the sword (or the body of the PC he suspects carries it), and then stepping through the portal that has opened at the castle and into Thousandbreaths, at which point he makes his way to the House at the Edge of Time to present the sword to his mistress. See Part Three for details on what happens if Nyrissa reclaims Briar.","morale":"The Horned Hunter fights to the death in his pursuit of Briar, but once he has the sword, he flees as detailed above.","source":"AP 36, Pathfinder RPG Bestiary 241"},{"name":"Athach","cr":12,"xp":19200,"race":"Athach","age_category":"Adult","alignment":"CE","size":"Huge","type":"humanoid","sub_types":["giant"],"init":1,"senses":["darkvision 60 ft.","low-light vision"],"ac":23,"ac_touch":9,"ac_flat_footed":22,"ac_mods":"+2 armor, +1 Dex, +12 natural,-2 size","hp":161,"hd":"14d8+98","hd_value":14,"fort":16,"ref":5,"will":7,"resists":["cold 10"],"speed":[{"type":"land","speed":50}],"melee":"sickle +19 (2d6+11), claw +17 (1d10+5), bite +17 (2d6+5 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"third claw"}],"strength":32,"dexterity":13,"constitution":25,"intelligence":7,"wisdom":12,"charisma":6,"baseatk":10,"cmb":23,"cmd":34,"feats":[{"feat":"Cleave"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Lunge"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":16},{"skill":"Fly","value":0},{"skill":"Perception","value":11},{"skill":"Stealth","value":0}],"languages":["Giant"],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 24; frequency 1/round for 6 rounds; effect 1d4 Str; cure 2 consecutive saves."},{"type":"Third Claw","kind":"Ex","details":"An athach's third claw attacks with a mind of its own-the athach can attack with its third claw as a swift action if it wishes."}],"gear":"leather armor, sickle","during_combat":"The athachs prefer to move about as they fight, using Lunge to reach foes that they can't reach and attacking with Vital Strike sickle blows and their third claws even if they move.","morale":"The athachs fight to the death.","source":"AP 36"},{"name":"The Misbegotten Troll","cr":16,"xp":76800,"race":"troll","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":11}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["giant"],"init":3,"senses":["darkvision 60 ft.","low-light vision"],"ac":29,"ac_touch":12,"ac_flat_footed":26,"ac_mods":"+12 armor, +3 Dex, +5 natural, -1 size","hp":268,"hd":"6d8+11d10+181","hd_value":17,"hp_mods":"regeneration 5 (acid or fire)","fort":21,"ref":8,"will":7,"save_mods":"+3 vs. fear","defensive_abilities":["bravery +3"],"speed":[{"type":"land","speed":30}],"melee":"+2 vicious ranseur +26 (2d6+17/19-20/x3 plus 2d6), bite +20 (1d8+8) or bite +25 (1d8+12), 2 claws +25 (1d6+14/19-20)","space":"10 ft.","reach":"10 ft. (15 ft. with ranseur)","special_attacks":[{"type":"rend","details":"2 claws, 1d6+7"}],"strength":26,"dexterity":16,"constitution":28,"intelligence":6,"wisdom":11,"charisma":4,"baseatk":15,"cmb":24,"cmd":37,"feats":[{"feat":"Critical Focus"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Critical (ranseur)"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Staggering Critical"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (ranseur, bite, claws)"},{"feat":"Weapon Specialization (ranseur, bite, claws)"}],"skills":[{"skill":"Perception","value":17}],"languages":["Giant"],"sq":["armor training 3"],"gear":"+3 full plate, +2 vicious ranseur, necklace of lovelies","during_combat":"The Misbegotten Troll enjoys the wounds his ranseur causes his enemies almost as much as those it causes to his own body, and howls in delight with each successful hit. He also takes great delight in breaking the weapons of other foes, and often makes sunder attacks against those who wield particularly large weapons. If he faces a foe that seems capable of staying inside the reach of his ranseur, he casts the weapon aside with a frustrated roar and uses both claws in battle.","morale":"The Misbegotten Troll fights to the death.","source":"AP 36"},{"name":"Lesser Jabberwock","cr":20,"xp":307200,"race":"Lesser Jabberwock","age_category":"Adult","alignment":"CE","size":"Huge","type":"dragon","sub_types":["air","fire"],"init":3,"senses":["blindsight 60 ft.","darkvision 120 ft.","low-light vision","scent"],"auras":["frightful presence (120 ft., DC 28)"],"ac":38,"ac_touch":12,"ac_flat_footed":34,"ac_mods":"+3 Dex, +1 dodge, +26 natural, -2 size","hp":387,"hd":"25d12+225","hd_value":25,"hp_mods":"fast healing 10","fort":23,"ref":17,"will":21,"dr":"15/vorpal","immunities":["fire","magic paralysis and sleep"],"resists":["acid 20","electricity 20","sonic 20"],"weaknesses":["fear of vorpal weaponry","vulnerable to cold"],"speed":[{"type":"fly","speed":60,"maneuverability":"poor"},{"type":"land","speed":40}],"melee":"bite +36 (3d6+13/19-20), 2 claws +36 (2d6+13/19-20 plus grab), 2 wings +31 (1d8+6), tail +31 (2d6+6)","ranged":"2 eye rays +26 touch (15d6/19-20 plus burn)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"burble"},{"type":"burn","details":"6d6, DC 31"},{"type":"whiffling"}],"strength":37,"dexterity":16,"constitution":29,"intelligence":8,"wisdom":25,"charisma":22,"baseatk":25,"cmb":40,"cmd":54,"feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite, claws, eye rays)"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":23},{"skill":"Intimidate","value":34},{"skill":"Knowledge (nature)","value":27},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":35}],"languages":["Common","Aklo","Draconic","Gnome","Sylvan"],"sq":["whiffling"],"special_abilities":[{"type":"Burble","kind":"Su","details":"A lesser jabberwock can burble once every 1d4 rounds as a standard action. This blast of strange noises and shouted nonsense in the various languages known to the jabberwock (and invariably some languages it doesn't know) affects all creatures within a 60-foot-radius spread-these creatures must make a DC 28 Will save or become confused for 1d4 rounds. Alternatively, the lesser jabberwock can focus its burble attack to create a 60-foot-line of sonic energy that inflicts 20d6 points of sonic damage (DC 28 Reflex save for half). The confusion effect is mind-affecting; both are sonic effects. The save DC is Charisma-based."},{"type":"Damage Reduction","kind":"Ex","details":"A lesser jabberwock's damage reduction can be bypassed only by weapons with the vorpal weapon enhancement."},{"type":"Eye Rays","kind":"Su","details":"The lesser jabberwock can project beams of fire from its eyes as a ranged touch attack as a standard action. It projects two beams, and can target different creatures with these beams if it wishes as long as both targets are within 30 ft. of each other. A creature that takes damage from an eye beam suffers burn."},{"type":"Fear of Vorpal Weaponry","kind":"Ex","details":"A lesser jabberwock knows that a vorpal weapon can kill it swiftly. As soon as it takes damage from a vorpal weapon, a lesser jabberwock becomes shaken. If it is hit by a critical threat from a vorpal weapon, whether or not the critical hit is confirmed, the jabberwock is staggered for the following round."},{"type":"Whiffling","kind":"Ex","details":"A lesser jabberwock's wings and violent motions create a significant amount of wind whenever it makes a full attack action. These winds surround the monster to a radius of 30 feet, and are treated as severe winds-ranged attacks suffer a -4 penalty to hit a lesser jabberwock when it is whiffling, and Medium creatures must make a DC 10 Strength check to approach the creature. Small or smaller creatures in this area that fail a DC 15 Strength check are blown away. See page 439 of the Pathfinder RPG Core Rulebook for further details on the effects of severe winds."}],"during_combat":"The lesser jabberwock races into the midst of the PCs on the first round of combat to make a vital strike with its bite. On the second round, it burbles to confuse the PCs that surround it. On following rounds, it makes full attacks-preferably against the PC wielding Briar. If the monster is reduced to fewer than 200 hit points, it takes to the air and circles, firing one eye ray per round with Vital Strike while it heals back up to at least 300 hit points before landing and entering melee again. If denied this level of mobility, the monster simply focuses its full attacks on single targets, hoping to take the PCs down one at a time. At your discretion, if the monster defeats the wielder of Briar, it could scoop up the weapon and take to the air. The gate through which Nyrissa sent the creature into the Material Plane is closed, so it must return to the First World via the portal at the Castle of Knives-it flies toward that site with all due haste, eager to return the hated weapon to its mistress.","morale":"The lesser jabberwock fights to the death.","source":"AP 36"},{"name":"Advanced Lightning Treant","cr":11,"xp":12800,"race":"lightning treant","age_category":"Adult","alignment":"NE","size":"Huge","type":"plant","templates_applied":"advanced","init":5,"senses":["low-light vision"],"ac":24,"ac_touch":9,"ac_flat_footed":23,"ac_mods":"+1 Dex, +15 natural, -2 size","hp":162,"hd":"12d8+108","hd_value":12,"hp_mods":"fast healing 10","fort":17,"ref":7,"will":9,"defensive_abilities":["electric healing"],"dr":"10/slashing","immunities":["electricity","fire","plant traits"],"speed":[{"type":"land","speed":40}],"melee":"2 slams +21 (2d8+14)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"double damage against objects"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"greater magic fang","details":"self only"}]},{"frequency":"at-will","spells":[{"spell":"faerie fire"}]},{"frequency":"1/day","spells":[{"spell":"chain lightning"}]},{"frequency":"3/day","spells":[{"spell":"call lightning storm"},{"spell":"lightning bolt"},{"spell":"protection from energy"}]}],"strength":32,"dexterity":13,"constitution":28,"intelligence":15,"wisdom":21,"charisma":15,"baseatk":9,"cmb":22,"cmd":33,"feats":[{"feat":"Cleave"},{"feat":"Greater Sunder"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":20},{"skill":"Stealth","value":8,"special":"+16 in forests"},{"skill":"Survival","value":17}],"languages":["Aklo"],"special_abilities":[{"type":"Double Damage Against Objects","kind":"Ex","details":"A lightning treant that makes a full attack against an object or structure deals double damage."},{"type":"Electric Healing","kind":"Ex","details":"Electricity damage heals a lightning treant 1 point of damage for every 3 points it would otherwise deal. If the amount would cause the lightning treant to exceed its full normal hit points, it gains any excess as temporary hit points-these temporary hit points last for 2 hours."}],"during_combat":"If a lightning treant can't reach the PCs, it uses its spell-like abilities to attack from afar, making sure to catch other treants in the area of effect if it can to provide healing.","morale":"The lightning treants fight to the death.","source":"AP 36, Tome of Horrors III 119"},{"name":"Kargstaad","cr":17,"xp":102400,"race":"frost giant","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":8}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["cold","giant"],"init":1,"senses":["low-light vision"],"ac":27,"ac_touch":11,"ac_flat_footed":25,"ac_mods":"+7 armor, +2 deflection, +1 Dex, +1 dodge, +9 natural, -2 rage, -1 size","hp":343,"hd":"14d8+8d12+228","hd_value":22,"fort":25,"ref":12,"will":18,"defensive_abilities":["rock catching improved uncanny dodge","trap sense +2"],"dr":"1/-","immunities":["cold"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":40}],"melee":"mwk cold iron handaxe +25 (1d8+23/19- 20/x3), 3 mwk cold iron handaxes +25 (1d8+11/19-20/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rage","details":"26 rounds/day"},{"type":"rage powers","details":"guarded stance [+2 + Con bonus], quick reflexes, swift foot +5 feet"}],"strength":36,"dexterity":13,"constitution":30,"intelligence":10,"wisdom":16,"charisma":9,"baseatk":18,"cmb":32,"cmd":44,"feats":[{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (handaxe)"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Multiweapon Fighting"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (handaxe)"}],"skills":[{"skill":"Climb","value":34},{"skill":"Intimidate","value":22},{"skill":"Perception","value":26}],"languages":["Giant"],"sq":["fast movement"],"gear":"+3 hide armor, masterwork cold iron handaxes (4), amulet of natural armor +3, ring of protection +2","during_combat":"Kargstaad rages at the start of any fight and uses Power Attack while in melee. If he can't engage foes in melee, he uproots tombstones and hurls them as thrown rocks.","morale":"Kargstaad fights to the death.","source":"AP 36, Pathfinder RPG Bestiary 149"},{"name":"Nightmare Rook","cr":16,"xp":76800,"race":"roc","gender":"Male","age_category":"Adult","alignment":"CE","size":"Colossal","type":"magical beast","sub_types":["augmented animal","evil"],"templates_applied":"advanced, awakened, nightmare","init":5,"senses":["darkvision 120 ft.","low-light vision"],"auras":["fear aura (60 ft., DC 26)"],"ac":30,"ac_touch":8,"ac_flat_footed":24,"ac_mods":"+5 Dex, +1 dodge, +22 natural, -8 size","hp":252,"hd":"24d8+144","hd_value":24,"hp_mods":"regeneration 5 (silver or good)","fort":20,"ref":19,"will":11,"defensive_abilities":["feign death"],"dr":"5/silver or good","immunities":["illusions"],"speed":[{"type":"fly","speed":80,"maneuverability":"perfect"},{"type":"land","speed":20}],"melee":"2 talons +23 (3d6+13/19-20), bite +23 (3d8+13/19-20)","space":"30 ft.","reach":"20 ft.","special_attacks":[{"type":"living nightmares"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"protection from good"}]}],"strength":36,"dexterity":20,"constitution":22,"intelligence":16,"wisdom":12,"charisma":18,"baseatk":18,"cmb":39,"cmd":55,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (talons, bite)"},{"feat":"Improved Iron Will"},{"feat":"Improved Natural Armor (3)"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Snatch"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":32},{"skill":"Intimidate","value":34},{"skill":"Knowledge (planes)","value":27},{"skill":"Perception","value":28},{"skill":"Stealth","value":22}],"languages":["Aklo","Sylvan"],"special_abilities":[{"type":"Fear Aura","kind":"Su","details":"Creatures affected by the Nightmare Rook's fear aura become shaken the first time they fail their save and cower in fear each round they fail a save thereafter. Once a creature succeeds on a saving throw against this effect, it is immune to the effect for 24 hours."},{"type":"Living Nightmares","kind":"Su","details":"The Nightmare Rook has the ability to inflict living nightmares on any non-native of the First World who sleeps in Thousandbreaths, at the rate of one nightmare per person per night. A living nightmare functions as detailed on page 15-this ability cannot be used in combat."}],"during_combat":"The Nightmare Rook uses Flyby Attack and Vital Strike bite attacks to devastating effect, relying on its fear aura and frightful presence to scatter its foes. If this tactic works, it uses Snatch to grab a PC and then flies off with its foe. If the Nightmare Rook makes it over the tree line, it is effectively out of reach of other players and free to travel to any other glade it wishes to drop its stolen PC-the bird has a particular fondness for dropping prey into the Mire (area G) or the Fruiting Orchard (area E). It can't drop a PC into the deep woods, as the nature of Thousandbreaths prevents such a stranding, and if a PC manages to wrestle out of the Rook's clutches while hanging over the vast green forest below, she falls a distance of well over 200 ft. to land at the edge of the glade from which she most recently left. If the Rook isn't able to separate the PCs, it lands and makes full attacks until reduced to 100 hit points or less, at which point it flies back up to its spire to heal and glare malevolently at the PCs.","morale":"If confronted at the top of its perch (a circular area 90 ft. in diameter), the Nightmare Rook fights to the death.","source":"AP 36, Pathfinder RPG Bestiary 236, Advanced Bestiary 187"}];
